import React, { useState, useEffect, useRef } from 'react';
import './../styles/Modal.css';

const Modal = ({ content, closeModal }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const modalRef = useRef(null);
  const imageRef = useRef(null);
  const textRef = useRef(null);
  const prevButtonRef = useRef(null);
  const nextButtonRef = useRef(null);

  useEffect(() => {
    setCurrentImageIndex(0);
  }, [content]);

  const handleOverlayClick = (e) => {
    // Close modal if click is outside interactive elements
    if (modalRef.current && modalRef.current === e.target) {
      closeModal();
    }
  };

  const goToNextSlide = () => {
    setCurrentImageIndex((prevIndex) =>
      prevIndex === content.images.length - 1 ? 0 : prevIndex + 1
    );
  };

  const goToPrevSlide = () => {
    setCurrentImageIndex((prevIndex) =>
      prevIndex === 0 ? content.images.length - 1 : prevIndex - 1
    );
  };

  if (!content || !content.text) {
    return null;
  }

  return (
    <div
      ref={modalRef}
      className={`modal ${content && content.text ? 'open' : ''}`}
      onClick={handleOverlayClick}
    >
      <div className="modal-content">
        <div className="modal-right">
          <div
            ref={textRef}
            className="text-content"
            dangerouslySetInnerHTML={{ __html: content.text }}
          />
        </div>
        <div className="modal-left">
          {content.carousel && content.images && content.images.length > 0 ? (
            <div className="carousel-container">
              {content.images.map((image, index) => (
                <div
                  ref={index === currentImageIndex ? imageRef : null}
                  className={`carousel-slide ${
                    index === currentImageIndex ? 'active' : ''
                  }`}
                  key={index}
                >
                  <img src={image} alt={`Slide ${index + 1}`} />
                </div>
              ))}
              {content.images.length > 1 && (
                <>
                  <button
                    ref={prevButtonRef}
                    className="prev"
                    onClick={goToPrevSlide}
                  >
                    <img src="/media/left.webp" alt="Previous" />
                  </button>
                  <button
                    ref={nextButtonRef}
                    className="next"
                    onClick={goToNextSlide}
                  >
                    <img src="/media/right.webp" alt="Next" />
                  </button>
                </>
              )}
            </div>
          ) : (
            content.image && (
              <img ref={imageRef} id="modalImg" src={content.image} alt="Modal" />
            )
          )}
        </div>
      </div>
    </div>
  );
};

export default Modal;
